using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BEOApply {
 const string A="Assets/Afrer_Seconds/05.Model/",P=A+"Props/B4/",E=A+"Environment/B4/";static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B4_ExperimentOperations/";static Dictionary<string,Material> mats=new Dictionary<string,Material>();static List<object> changes=new List<object>();static int chairs,lights;
 static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);
 static GameObject Child(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static void Import(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);foreach(var file in Directory.GetFiles(E+"Materials","B4O_*.mat")){var m=AssetDatabase.LoadAssetAtPath<Material>(file.Replace('\\','/'));mats[m.name]=m;}
  for(int i=23;i<=42;i++){string n="BX_Display_"+i.ToString("00"),path=P+"Textures/"+n+".png";var ti=(TextureImporter)AssetImporter.GetAtPath(path);ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.wrapMode=TextureWrapMode.Clamp;ti.filterMode=FilterMode.Trilinear;ti.textureCompression=TextureImporterCompression.CompressedHQ;ti.SaveAndReimport();var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=n};m.SetColor("_BaseColor",Color.white);m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));m.SetFloat("_Smoothness",.22f);m.SetFloat("_SpecularHighlights",0);if(i<41){m.SetTexture("_EmissionMap",AssetDatabase.LoadAssetAtPath<Texture2D>(path));m.SetColor("_EmissionColor",Color.white*.65f);m.EnableKeyword("_EMISSION");m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.BakedEmissive;}AssetDatabase.CreateAsset(m,P+"Materials/"+n+".mat");mats[n]=m;}
  foreach(var file in Directory.GetFiles(P,"BX_*.fbx")){string path=file.Replace('\\','/');var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(var kv in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),kv.Key),kv.Value);mi.SaveAndReimport();}}
 static GameObject Place(string name,string asset,Transform parent,Vector3 pos,float yaw,bool mesh,Vector3 size,Vector3 center){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(asset),parent);g.name=name;g.transform.localPosition=pos;g.transform.localRotation=Quaternion.Euler(0,yaw,0);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var rr in g.GetComponentsInChildren<Renderer>())rr.sharedMaterials=rr.sharedMaterials.Select(m=>mats.TryGetValue(m.name,out var mapped)?mapped:m).ToArray();if(mesh){foreach(var mf in g.GetComponentsInChildren<MeshFilter>())mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;}else{var bc=g.AddComponent<BoxCollider>();bc.size=size;bc.center=center;}return g;}
 static void Chair(Transform parent,Vector3 p,string suffix){var g=Place(parent.name+"_作業椅子_"+suffix,A+"Props/B5/SF_TaskChair.fbx",parent,p,180,false,new Vector3(.66f,1.12f,.67f),new Vector3(0,.564f,0));g.name=parent.name+"_작업의자_"+suffix;foreach(var rr in g.GetComponentsInChildren<Renderer>())rr.sharedMaterials=rr.sharedMaterials.Select(m=>{foreach(string k in new[]{"Fabric","Rubber","Dark","Steel","Coat"})if(m.name.Contains(k))return mats["B4O_"+k];return mats["B4O_Coat"];}).ToArray();chairs++;}
 static void LightAt(Transform parent,Vector3 p,float intensity,float range){var g=Child("등기구_실제광원_"+(lights+1).ToString("00"),parent);g.transform.localPosition=p;g.transform.localRotation=Quaternion.Euler(90,0,0);var l=g.AddComponent<Light>();l.type=LightType.Spot;l.spotAngle=110;l.innerSpotAngle=70;l.intensity=intensity;l.range=range;l.color=new Color(.94f,.97f,1);l.shadows=LightShadows.Soft;l.shadowBias=.01f;l.shadowNormalBias=.015f;l.shadowNearPlane=.1f;var u=l.GetUniversalAdditionalLightData();u.usePipelineSettings=false;var so=new SerializedObject(u);so.FindProperty("m_AdditionalLightsShadowResolutionTier").intValue=0;so.ApplyModifiedPropertiesWithoutUndo();lights++;}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;if(root.Find("B4_실험운용설비"))throw new Exception("Already applied. Repair target only.");var plan=JObject.Parse(File.ReadAllText(H+"layout.json"));Import();var map=new Dictionary<string,int>{{"C01",31},{"C02",36},{"C03",33},{"C04",38},{"C05",39},{"W01",34},{"W02",29},{"W03",30},{"E01",38},{"E02",40},{"E03",37},{"N01",32},{"S01",28}};
  foreach(var rr in root.GetComponentsInChildren<Renderer>()){var pg=PrefabUtility.GetNearestPrefabInstanceRoot(rr.gameObject);if(!pg||!PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(pg).Contains("/Props/"))continue;string code=map.Keys.FirstOrDefault(k=>pg.name.StartsWith("B4_"+k+"_"));if(code==null)continue;var before=rr.sharedMaterials;bool changed=false;var after=before.Select(m=>{if(!m||!m.name.Contains("Display")||m.name=="BF_Display_17")return m;int id=map[code];if(m.name=="BF_Display_13")id=38;if(m.name=="BF_Display_14")id=39;if(m.name=="BF_Display_15")id=29;if(m.name=="BF_Display_16")id=34;changed=true;return mats["BX_Display_"+id.ToString("00")];}).ToArray();if(changed){rr.sharedMaterials=after;PrefabUtility.RecordPrefabInstancePropertyModifications(rr);changes.Add(new{name=pg.name,before=before.Select(m=>m?m.name:"null"),after=after.Select(m=>m?m.name:"null")});}}
  var full=Child("B4_실험운용설비",root).transform;root.name="B4_능력측정발달강화층_V0.03";
  foreach(var r in plan["rooms"]){string code=(string)r["id"];var room=Child("B4_"+code+"_실험운용",full).transform;room.localPosition=new Vector3((float)r["x"],0,-(float)r["v"]);
   foreach(var p in plan["newPlacements"].Where(q=>(string)q["room"]==code)){var g=Place((string)p["name"],(string)p["asset"],room,V(p["position"]),(float)p["yaw"],(bool)p["meshCollider"],V(p["size"]),V(p["center"]));string m=(string)p["model"];
    if(m=="BX_ObservationBooth"){Chair(g.transform,new Vector3(-1.02f,0,.45f),"01");Chair(g.transform,new Vector3(1.02f,0,.45f),"02");LightAt(g.transform,new Vector3(-.82f,2.35f,-.15f),2.6f,5);LightAt(g.transform,new Vector3(.82f,2.35f,-.15f),2.6f,5);}
    if(m=="BX_OperatorIsland"||m=="BX_ProtocolTable"){Chair(g.transform,new Vector3(-.78f,0,1.10f),"01");Chair(g.transform,new Vector3(.78f,0,1.10f),"02");}
    if(m=="BX_DualReviewStation")Chair(g.transform,new Vector3(-.55f,0,.95f),"01");
    if(m=="BX_SubjectCheckIn")Chair(g.transform,new Vector3(-.55f,0,.92f),"01");
    if(m=="BX_TaskLightPole")LightAt(g.transform,new Vector3(0,2.277f,.4f),3.2f,6);
   }
  }
  foreach(var t in full.GetComponentsInChildren<Transform>())if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var rr in t.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(rr);}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);File.WriteAllText(H+"screen_changes.json",JsonConvert.SerializeObject(changes,Formatting.Indented));var result=new{scene=s.path,addedPlacements=plan["newPlacements"].Count(),addedChairs=chairs,addedLights=lights,updatedScreenRenderers=changes.Count,renderers=root.GetComponentsInChildren<Renderer>().Length,colliders=root.GetComponentsInChildren<Collider>().Length,lights=root.GetComponentsInChildren<Light>().Length};File.WriteAllText(R+"/Docs/검수/2026-11-08_B4_ExperimentOperations/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
}
